raw repos/dmtest/gradle-conventions/raw/:
plugins {
  `kotlin-dsl`
}

group = "com.dmtest.gradle"

gradlePlugin {
  plugins {
    create("conventions") {
      id = "com.dmtest.conventions"
      implementationClass = "com.dmtest.gradle.ConventionsPlugin"
    }
  }
}

